SET ROLE authenticated;
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000151","session_id":"00000000-0000-4000-c000-000000000151"}';
SELECT public.service_create('00000000-0000-4000-e000-000000000151','{"code":"FINANCE15","name":"Servico financeiro","category":"Copias","unit":"pagina","price_cents":10000,"effective_from":null,"person_required":false,"participants_min":0,"approval_required":false,"signature_required":false,"settlement_required":true,"required_capabilities":["services.perform"],"fields":[],"checklist":[],"quantity_min":1,"quantity_max":1000,"max_discount_bps":1000,"max_surcharge_bps":5000,"allow_courtesy":true,"allow_price_override":true}','Servico ficticio para regressao isolada16',gen_random_uuid());
SELECT test.correction_fixture() AS f \gset
SELECT public.correction_operate('00000000-0000-4000-e000-000000000151',test.correction_op(:'f',2000,false)) AS logical \gset
SELECT test.assert_true((SELECT e->>'refundable_cents'='6000' FROM jsonb_array_elements(:'logical'::jsonb->'entries')e WHERE e->>'kind'='received') AND :'logical'::jsonb->'session'->>'refunded_cents'='0','16 foco: estorno logico nao conta como dinheiro devolvido no original');
SELECT public.correction_sources('00000000-0000-4000-e000-000000000151',(:'f'::jsonb->>'session')::uuid,'refund','',1)->'items'->0->>'reversal_id' AS reversalid \gset
SELECT public.correction_operate('00000000-0000-4000-e000-000000000151',jsonb_build_object('kind','refund','session_id',:'f'::jsonb->'session','expected_version',3,'idempotency_key',gen_random_uuid(),'reversal_id',:'reversalid','amount_cents',2000,'reason','Devolucao efetiva local isolada16','evidence','Evidencia manual sem dado pessoal16')) AS corrected \gset
SELECT test.assert_true(:'corrected'::jsonb->'session' @> '{"cash_cents":14000,"refunded_cents":2000}' AND :'corrected'::jsonb->'payments'->'items'->0 @> '{"reversed_cents":2000,"refunded_cents":2000,"pending_refund_cents":0}','16 P3 focado: devolucao posterior efetiva apos novas referencias');
RESET ROLE;
SELECT test.assert_true((SELECT count(*) FROM public.audit_events WHERE action IN('payments.allocation_reversed','payments.refund_paid'))=2 AND NOT EXISTS(SELECT FROM public.audit_events e LEFT JOIN private.payment_reversals v ON v.office_id=e.office_id AND v.id::text=e.changes->>'reversal_id' LEFT JOIN private.cash_entries l ON l.office_id=e.office_id AND l.id::text=e.changes->>'entry_id' WHERE e.action='payments.allocation_reversed' AND(v.id IS NULL OR l.id IS NULL OR l.id<>v.entry_id OR l.kind<>'allocation_reversed')) AND NOT EXISTS(SELECT FROM public.audit_events e LEFT JOIN private.payment_refunds f ON f.office_id=e.office_id AND f.id::text=e.changes->>'refund_id' LEFT JOIN private.cash_entries l ON l.office_id=e.office_id AND l.id::text=e.changes->>'entry_id' WHERE e.action='payments.refund_paid' AND(f.id IS NULL OR l.id IS NULL OR l.id<>f.entry_id OR l.kind<>'refund_paid')),'16 P3 focado: entry_id identifica cash_entries e IDs de correcao separados');
SELECT test.assert_true(NOT EXISTS(SELECT FROM public.audit_events WHERE changes::text ~ 'Evidencia|Motivo privado') AND(SELECT private.safe_audit_changes('{"reason":"Privado","evidence":"Privada","reversal_id":"00000000-0000-4000-a000-000000000161","refund_id":"00000000-0000-4000-a000-000000000161"}')='{"reversal_id":"00000000-0000-4000-a000-000000000161","refund_id":"00000000-0000-4000-a000-000000000161"}'::jsonb),'16 P3 focado: somente referencias tecnicas aceitas sem notas livres');
